//! Exact Architect of Ascension and Edge of Null sources, with generic tap-payment reminders.
use ironsmith::{CardDefinition,GameState,ObjectId,PlayerId,Zone};
use ironsmith::decision::{LegalAction,SelectFirstDecisionMaker,compute_legal_actions};
const A:PlayerId=PlayerId(0);
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../../../fixtures/custom_mechanics/revolution-syzygy-source-complete.json")).unwrap()}
fn definitions_for(name:&str)->[CardDefinition;2]{let fixture=fixture();let card=fixture["mechanics"][0]["representative_cards"].as_array().unwrap().iter().find(|card|card["name"]==name).unwrap();let text=card["executable_text"].as_str().unwrap();let(artifact,direct)=ironsmith_compiler::word_claims::with_enforcement_options(true,true,||ironsmith_compiler_runtime::compile_to_artifact(name,text,false)).unwrap();assert!(direct.spell_effect.is_none());let decoded=ironsmith_compiled_artifact::CompiledCardArtifact::from_json(&artifact.to_json().unwrap()).unwrap();assert_eq!(artifact,decoded);[direct,ironsmith_runtime_catalog::artifact_materializer::materialize_artifact(&decoded).unwrap()]}
fn definitions(equipment:bool)->[CardDefinition;2]{definitions_for(if equipment{"Edge of Null"}else{"Architect of Ascension"})}
fn game()->GameState{let mut game=GameState::new(vec!["A".into(),"B".into()],20);game.turn.active_player=A;game.turn.priority_player=Some(A);game.turn.phase=ironsmith::game_state::Phase::FirstMain;game.turn.step=None;game}
fn witness(game:&mut GameState)->ObjectId{let definition=ironsmith_compiler_runtime::compile_to_runtime_definition("Tap witness","Type: Creature\nPower/Toughness: 1/1",false).unwrap();game.create_object_from_definition(&definition,A,Zone::Battlefield)}
fn finish(game:&mut GameState,action:LegalAction){use ironsmith::game_loop::{PriorityLoopState,PriorityResponse,apply_priority_response_with_dm,apply_decision_context_with_dm};let mut state=PriorityLoopState::new(2);let mut queue=ironsmith::triggers::TriggerQueue::new();let mut dm=SelectFirstDecisionMaker;let mut progress=apply_priority_response_with_dm(game,&mut queue,&mut state,&PriorityResponse::PriorityAction(action),&mut dm).unwrap();for _ in 0..64{if !state.has_pending_action(){return}let ironsmith::GameProgress::NeedsDecisionCtx(ctx)=progress else{panic!("{progress:?}")};progress=apply_decision_context_with_dm(game,&mut queue,&mut state,&ctx,&mut dm).unwrap()}panic!("payment unfinished")}
fn activation(game:&GameState,source:ObjectId)->Option<LegalAction>{compute_legal_actions(game,A).unwrap().into_iter().find(|action|matches!(action,LegalAction::ActivateAbility{source:id,..}if *id==source))}
#[test]fn full_architect_source_pays_only_generic_mana_with_creatures_and_excludes_itself_from_activation(){for definition in definitions(false){let mut game=game();let source=game.create_object_from_definition(&definition,A,Zone::Battlefield);let first=witness(&mut game);game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::Blue,1);assert!(activation(&game,source).is_none(),"source+one other cannot pay two generic activation mana");let second=witness(&mut game);let chosen=activation(&game,source).expect("two other creatures and actual blue mana pay2U");finish(&mut game,chosen);assert!(game.is_tapped(first));assert!(game.is_tapped(second));assert!(!game.is_tapped(source));assert_eq!(game.player(A).unwrap().mana_pool.total(),0);ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut SelectFirstDecisionMaker).unwrap();assert!(game.object_has_ability(source,&ironsmith::static_abilities::StaticAbility::flying()));assert!(game.object_has_ability(source,&ironsmith::static_abilities::StaticAbility::vigilance()));}}
#[test]fn both_full_sources_can_be_cast_using_creatures_but_colored_symbols_still_require_mana(){for equipment in [false,true]{for definition in definitions(equipment){let mut game=game();let creatures:Vec<_>=(0..4).map(|_|witness(&mut game)).collect();let card=game.create_object_from_definition(&definition,A,Zone::Hand);let find=|game:&GameState|compute_legal_actions(game,A).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell{spell_id,..}if *spell_id==card));if !equipment{assert!(find(&game).is_none(),"generic-only tapping cannot payUU");game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::Blue,2);}let chosen=find(&game).expect("four creatures pay the four generic mana");finish(&mut game,chosen);for id in creatures{assert!(game.is_tapped(id));}assert_eq!(game.player(A).unwrap().mana_pool.total(),0);ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut SelectFirstDecisionMaker).unwrap();assert!(game.objects_in_zone(Zone::Battlefield).into_iter().any(|id|game.object(id).is_some_and(|object|object.name==if equipment{"Edge of Null"}else{"Architect of Ascension"})));}}}
#[test]fn exact_equipment_activation_uses_the_same_generic_only_payment_adapter(){for definition in definitions(true){let mut game=game();let equipment=game.create_object_from_definition(&definition,A,Zone::Battlefield);let creatures:Vec<_>=(0..4).map(|_|witness(&mut game)).collect();let chosen=activation(&game,equipment).expect("four creatures pay equip4");finish(&mut game,chosen);for id in creatures{assert!(game.is_tapped(id));}ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut SelectFirstDecisionMaker).unwrap();assert!(game.object(equipment).unwrap().attached_to.is_some());}}

#[test]fn all_twenty_one_authored_sources_compile_without_erasing_siblings_and_roundtrip(){let fixture=fixture();let cards=fixture["mechanics"][0]["representative_cards"].as_array().unwrap();assert_eq!(cards.len(),21);for card in cards{let name=card["name"].as_str().unwrap();assert!(card["original_text"].as_str().unwrap().contains("Syzygy"));for definition in definitions_for(name){assert!(definition.abilities.iter().any(|ability|matches!(&ability.kind,ironsmith::ability::AbilityKind::Static(rule) if rule.compiled_model().is_some_and(|model|matches!(&model.payload,ironsmith_core::StaticAbilityPayload::GenericManaTapPayment {spells:true,activated_abilities:true,exclude_source:true,name:Some(label),..} if label=="syzygy")))),"{name}: missing complete typed payment policy");}}}
fn named_spell(name:&str)->CardDefinition{let text=format!("Mana cost: {{1}}\nType: Artifact\nFor each generic mana in this spell's total cost, you may tap an untapped creature you control rather than pay that mana. This generic tap payment is named {name}.");ironsmith_compiler_runtime::compile_to_runtime_definition("Named tap spell",&text,false).unwrap()}
fn cast_action(game:&GameState,card:ObjectId)->Option<LegalAction>{compute_legal_actions(game,A).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell{spell_id,..}if *spell_id==card))}
fn named_activation(name:&str)->CardDefinition{let text=format!("Type: Artifact\nFor each generic mana in the total cost of this permanent's abilities, you may tap another untapped creature you control rather than pay that mana. This generic tap payment is named {name}.\n{{1}}: You gain 1 life.");ironsmith_compiler_runtime::compile_to_runtime_definition("Alternative named tap source",&text,false).unwrap()}
#[test]fn actual_stardust_token_prohibition_is_exact_named_and_enforced_by_activation_payment(){for definition in definitions_for("Stardust Behemoth"){let mut game=game();let stardust=game.create_object_from_definition(&definition,A,Zone::Battlefield);let paid:Vec<_>=(0..3).map(|_|witness(&mut game)).collect();game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::White,1);let chosen=activation(&game,stardust).unwrap();finish(&mut game,chosen);ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut SelectFirstDecisionMaker).unwrap();for id in paid{assert!(game.is_tapped(id));}game.tap(stardust);let token=game.objects_in_zone(Zone::Battlefield).into_iter().find(|id|game.object(*id).is_some_and(|object|object.name=="Elemental")).unwrap();assert!(!game.is_tapped(token));assert!(game.object_has_ability(token,&ironsmith::static_abilities::StaticAbility::cant_block()));
 let denied=game.create_object_from_definition(&named_activation("syzygy"),A,Zone::Battlefield);assert!(activation(&game,denied).is_none(),"actual source token cannot pay named syzygy activation");
 // A forged ordinary activation cannot bypass the same final payment planner.
 let ability_index=game.current_abilities(denied).unwrap().iter().position(|ability|matches!(&ability.kind,ironsmith::ability::AbilityKind::Activated(_))).unwrap();let mut rejected=game.clone();let mut queue=ironsmith::triggers::TriggerQueue::new();let mut state=ironsmith::game_loop::PriorityLoopState::new(2);let mut dm=SelectFirstDecisionMaker;let mut progress=ironsmith::game_loop::apply_priority_response_with_dm(&mut rejected,&mut queue,&mut state,&ironsmith::game_loop::PriorityResponse::PriorityAction(LegalAction::ActivateAbility{source:denied,ability_index}),&mut dm);for _ in 0..16{if !state.has_pending_action(){break}let Ok(ironsmith::GameProgress::NeedsDecisionCtx(ctx))=progress else{break};progress=ironsmith::game_loop::apply_decision_context_with_dm(&mut rejected,&mut queue,&mut state,&ctx,&mut dm);}assert!(rejected.stack.is_empty());assert!(!rejected.is_tapped(token));
 let forbidden_spell=game.create_object_from_definition(&named_spell("syzygy"),A,Zone::Hand);assert!(cast_action(&game,forbidden_spell).is_none(),"the same prohibition applies to spell generic payments");
 let mut rejected_cast=game.clone();let mut queue=ironsmith::triggers::TriggerQueue::new();let mut state=ironsmith::game_loop::PriorityLoopState::new(2);let mut progress=ironsmith::game_loop::apply_priority_response_with_dm(&mut rejected_cast,&mut queue,&mut state,&ironsmith::game_loop::PriorityResponse::PriorityAction(LegalAction::CastSpell{spell_id:forbidden_spell,from_zone:Zone::Hand,casting_method:ironsmith::alternative_cast::CastingMethod::Normal}),&mut SelectFirstDecisionMaker);for _ in 0..16{if !state.has_pending_action(){break}let Ok(ironsmith::GameProgress::NeedsDecisionCtx(ctx))=progress else{break};progress=ironsmith::game_loop::apply_decision_context_with_dm(&mut rejected_cast,&mut queue,&mut state,&ctx,&mut SelectFirstDecisionMaker);}assert!(rejected_cast.stack.is_empty());assert!(!rejected_cast.is_tapped(token));assert_eq!(rejected_cast.object(forbidden_spell).unwrap().zone,Zone::Hand);
 for name in ["stellar weaving","syzygy craft"]{let mut allowed_cast=game.clone();let spell=allowed_cast.create_object_from_definition(&named_spell(name),A,Zone::Hand);let chosen=cast_action(&allowed_cast,spell).expect("same token can pay a different exact named spell price");finish(&mut allowed_cast,chosen);assert!(allowed_cast.is_tapped(token));assert_eq!(allowed_cast.stack.len(),1);}
 for name in ["stellar weaving","syzygy craft"]{let mut allowed=game.clone();let source=allowed.create_object_from_definition(&named_activation(name),A,Zone::Battlefield);let chosen=activation(&allowed,source).expect("exact other label admits the very same creature");finish(&mut allowed,chosen);assert!(allowed.is_tapped(token));ironsmith::game_loop::resolve_stack_entry_with(&mut allowed,&mut SelectFirstDecisionMaker).unwrap();assert_eq!(allowed.player(A).unwrap().life,21);}
}}

fn synthetic_definitions(name:&str,text:&str)->[CardDefinition;2]{let(artifact,direct)=ironsmith_compiler::word_claims::with_enforcement_options(true,true,||ironsmith_compiler_runtime::compile_to_artifact(name,text,false)).unwrap();let restored=ironsmith_compiled_artifact::CompiledCardArtifact::from_json(&artifact.to_json().unwrap()).unwrap();[direct,ironsmith_runtime_catalog::artifact_materializer::materialize_artifact(&restored).unwrap()]}
#[test]fn activation_half_is_battlefield_only_for_hand_and_graveyard_abilities(){
 for (name,zone,ability) in [("Hand ability",Zone::Hand,"Cycling {1}"),("Graveyard ability",Zone::Graveyard,"{1}, Exile this card from your graveyard: You gain 1 life.")]{
  let text=format!("Type: Creature\nPower/Toughness: 1/1\nFor each generic mana in the total cost of this permanent's abilities, you may tap another untapped creature you control rather than pay that mana. This generic tap payment is named stellar weaving.\n{ability}");
  for definition in synthetic_definitions(name,&text){let mut game=game();let resource=witness(&mut game);let source=game.create_object_from_definition(&definition,A,zone);assert!(activation(&game,source).is_none(),"{zone:?} ability cannot borrow battlefield-only permission");game.player_mut(A).unwrap().mana_pool.add(ironsmith::mana::ManaSymbol::Colorless,1);let chosen=activation(&game,source).expect("ordinary actual mana still pays the nonbattlefield ability");finish(&mut game,chosen);assert!(!game.is_tapped(resource));assert_eq!(game.player(A).unwrap().mana_pool.total(),0);}
 }
}
fn composition_definitions(artifact_only:bool)->[CardDefinition;2]{
 let unit=ironsmith::mana::ManaCost::from_pips(vec![vec![ironsmith::mana::ManaSymbol::Generic(1)]]);
 let scoped=if artifact_only{unit.with_artifact_tap_payment()}else{unit.with_waterbend()};let mana=scoped.add_generic(2);
 let builder=ironsmith_compiler::CardDefinitionBuilder::new(ironsmith_compiler::ids::CardId::new(),"Scoped tap composition").mana_cost(mana);
 let text="Type: Artifact\nFor each generic mana in this spell's total cost, you may tap an untapped creature you control rather than pay that mana. This generic tap payment is named stellar weaving.";
 let(artifact,direct)=ironsmith_compiler::word_claims::with_enforcement_options(true,true,||ironsmith_compiler_runtime::compile_builder_to_artifact(builder,text,false)).unwrap();let restored=ironsmith_compiled_artifact::CompiledCardArtifact::from_json(&artifact.to_json().unwrap()).unwrap();[direct,ironsmith_runtime_catalog::artifact_materializer::materialize_artifact(&restored).unwrap()]
}
#[test]fn supplemental_named_payment_preserves_original_artifact_capacity_and_waterbend_receipt(){
 for artifact_only in [false,true]{for definition in composition_definitions(artifact_only){
  let mut game=game();let resource_definition=ironsmith_compiler_runtime::compile_to_runtime_definition("Artifact tap resource","Type: Artifact",false).unwrap();
  // Artifact IDs precede creature IDs, forcing the planner to respect the
  // original one-unit scope rather than greedily using both artifacts.
  let first=game.create_object_from_definition(&resource_definition,A,Zone::Battlefield);let second=game.create_object_from_definition(&resource_definition,A,Zone::Battlefield);let creature=witness(&mut game);let card=game.create_object_from_definition(&definition,A,Zone::Hand);
  assert!(cast_action(&game,card).is_none(),"one native tap unit plus one named creature cannot pay3generic");
  let other=witness(&mut game);let chosen=cast_action(&game,card).expect("one artifact and two creatures jointly pay distinct permitted shares");finish(&mut game,chosen);
  assert_eq!(usize::from(game.is_tapped(first))+usize::from(game.is_tapped(second)),1,"native artifact capacity remains1");assert!(game.is_tapped(creature));assert!(game.is_tapped(other));
  let mut queue=ironsmith::triggers::TriggerQueue::new();ironsmith::game_loop::drain_pending_trigger_events_with_dm(&mut game,&mut queue,&mut SelectFirstDecisionMaker).unwrap();
  let receipts:Vec<_>=game.turn_store.turn_history.event_records.iter().filter_map(|record|record.event.downcast::<ironsmith::events::KeywordActionEvent>()).filter(|event|event.action==ironsmith::events::KeywordActionKind::Waterbend).map(|event|event.amount).collect();
  assert_eq!(receipts,if artifact_only{vec![]}else{vec![1]},"only the original authored Waterbend1 completion survives; named taps do not fabricate a different amount or event");
 }}
}

